[{"order":1,"type":"heading","text":"Computed Properties and Watchers (watch vs watchEffect) in Vue.js"},{"order":2,"type":"paragraph","text":"Vue.js offers reactive mechanisms to execute code in response to state changes. Choosing the right tool between computed properties, watch, and watchEffect is crucial for application performance and maintainability."},{"order":3,"type":"heading","text":"1. Computed Properties"},{"order":4,"type":"paragraph","text":"Computed properties are used to declarative define derived state. They are heavily optimized because they cache their result based on their reactive dependencies."},{"order":5,"type":"code","text":"import { ref, computed } from 'vue';

const firstName = ref('John');
const lastName = ref('Doe');

// Computed property automatically updates when firstName or lastName changes
const fullName = computed(() => firstName.value + ' ' + lastName.value);"},{"order":6,"type":"heading","text":"2. Watchers (watch)"},{"order":7,"type":"paragraph","text":"The watch function is designed for side effects, such as performing asynchronous operations, triggering mutations, or executing DOM operations when a specific reactive reference changes."},{"order":8,"type":"code","text":"import { ref, watch } from 'vue';

const searchQuery = ref('');

watch(searchQuery, async (newValue, oldValue) => {
  console.log('Search query changed from ' + oldValue + ' to ' + newValue);
  // Perform async operations like API calls
});"},{"order":9,"type":"heading","text":"3. Automatic Tracking (watchEffect)"},{"order":10,"type":"paragraph","text":"Unlike standard watch which requires explicitly passing the source, watchEffect runs the callback immediately while automatically tracking any reactive dependencies accessed synchronously within the function body."},{"order":11,"type":"code","text":"import { ref, watchEffect } from 'vue';

const userId = ref(1);

watchEffect(() => {
  // Automatically tracks userId.value
  console.log('Fetching data for user ID: ' + userId.value);
});"},{"order":12,"type":"heading","text":"Summary of Differences"},{"order":13,"type":"bullet_point","text":"Computed: Best for transforming data synchronously and returning a cached value."},{"order":14,"type":"bullet_point","text":"Watch: Best for side effects where you need to know both the old and new values of a specific source."},{"order":15,"type":"bullet_point","text":"WatchEffect: Best for side effects that automatically run on load and re-run whenever any internal reactive property changes without explicitly declaring dependencies."}]
